import math

def min_time_to_rescue(x1, y1, x2, y2, v, t, vx, vy, wx, wy):
    target = (x2 - x1, y2 - y1)

    def dist(a, b):
        return math.sqrt(a[0]**2 + a[1]**2)

    def dot(a, b):
        return a[0] * b[0] + a[1] * b[1]

    def cross(a, b):
        return a[0] * b[1] - a[1] * b[0]

    def angle_between(a, b):
        cos_theta = dot(a, b) / (dist(a, (0, 0)) * dist(b, (0, 0)))
        return math.acos(cos_theta)

    def can_reach_with_wind(wind, time_left, target):
        wind_speed = dist(wind, (0, 0))
        if wind_speed == 0:
            return False

        perpendicular_wind = (-wind[1], wind[0])
        if dot(perpendicular_wind, target) >= 0:
            return True

        angle = angle_between(wind, target)
        reachable_distance = v * time_left - wind_speed * time_left * math.sin(angle)
        return dist(target, (0, 0)) <= reachable_distance

    def binary_search(time):
        lo, hi = 0, time + t
        while hi - lo > 1e-7:
            mid = (lo + hi) / 2
            if mid <= t:
                if can_reach_with_wind((vx, vy), mid, target):
                    hi = mid
                else:
                    lo = mid
            else:
                remaining_target = (target[0] - (vx * mid + wx * (mid - t)), 
                                  target[1] - (vy * mid + wy * (mid - t)))
                if dist(remaining_target, (0, 0)) <= v * (mid - t):
                    hi = mid
                else:
                    lo = mid
        return lo

