def count_painted_cells(n, segments):
    from collections import defaultdict

    row_ranges = defaultdict(list)
    col_ranges = defaultdict(list)

    for x1, y1, x2, y2 in segments:
        if x1 == x2:
            col, start, end = x1, min(y1, y2), max(y1, y2)
            col_ranges[col].append((start, end))
        elif y1 == y2:
            row, start, end = y1, min(x1, x2), max(x1, x2)
            row_ranges[row].append((start, end))

    def merge_ranges(ranges):
        if not ranges:
            return 0
        ranges.sort()
        merged = [ranges[0]]
        for start, end in ranges[1:]:
            if start <= merged[-1][1]:
                merged[-1] = (merged[-1][0], max(merged[-1][1], end))
            else:
                merged.append((start, end))
        return sum(end - start for start, end in merged)

    total_cells = 0
    for row, ranges in row_ranges.items():
        total_cells += merge_ranges(ranges)
    for col, ranges in col_ranges.items():
        total_cells += merge_ranges(ranges)

    return total_cells

