def parse_compressed_string(blocks):
    result = []
    current_len, current_char = 0, ''
    for block in blocks:
        length, char = map(int, block.split('-'))
        char = chr(char + ord('a') - 1)
        if current_char == char:
            current_len += length
        else:
            if current_char:
                result.append((current_len, current_char))
            current_len, current_char = length, char
    if current_char:
        result.append((current_len, current_char))
    return result

def preprocess_z_function(s):
    n = len(s)
    z = [0] * n
    l, r = 0, 0
    for i in range(1, n):
        if i <= r:
            z[i] = min(r - i + 1, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] - 1 > r:
            l, r = i, i + z[i] - 1
    return z

def count_occurrences(t_blocks, s_blocks):
    s = ''.join(c * l for l, c in s_blocks)
    if not s:
        return 0

    t = ''.join(c * l for l, c in t_blocks)
    concatenated = s + '#' + t
    z_function = preprocess_z_function(concatenated)

    result = 0
    s_len = len(s)
    for i in range(len(s) + 1, len(concatenated)):
        if z_function[i] == s_len:
            result += 1

    return result

