    min_probs = list(map(float, data[n+1:2*n+1]))

    # Initialize the probability distributions for the dices
    a_probs = [0] * (2*n)
    b_probs = [0] * (2*n)

    # Calculate the probabilities for the combined outcomes
    combined_probs = [0] * (2*n + 1)
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            combined_probs[max(i, j)] += max_probs[i-1] * min_probs[j-1] / max_probs[max(i, j) - 1]

    # Normalize the combined probabilities
    combined_sum = sum(combined_probs[1:])
    for i in range(1, 2*n + 1):
        combined_probs[i] /= combined_sum

