    from collections import defaultdict
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def is_vertex_cover(subset):
        for u, vs in graph.items():
            if u not in subset:
                if all(v not in subset for v in vs):
                    return False
        return True

