        # Tree case
        leaves = [u for u in range(1, n + 1) if len(graph[u]) == 1]
        if len(leaves) >= 2:
            return f"1\n{leaves[0]}\n{n - 1}\n{' '.join(map(str, [i for i in range(1, n + 1) if i != leaves[0]))}"

    # General case
    visited = [False] * (n + 1)
    color = [None] * (n + 1)

    def dfs(u, c):
        visited[u] = True
        color[u] = c
        for v in graph[u]:
            if not visited[v]:
                if not dfs(v, not c):
                    return False
            elif color[v] == color[u]:
