import heapq

def huffman_encoding(n, c0, c1):
    if c0 > c1:
        c0, c1 = c1, c0
    heap = [1] * n
    heapq.heapify(heap)

    while len(heap) > 1:
        a = heapq.heappop(heap)
        b = heapq.heappop(heap)
        heapq.heappush(heap, a + b)

    total_cost = 0
    for _ in range(n):
        total_cost += heap[0]
        if heap[0] % 2 == 0:
            heap[0] //= 2
        else:
            heap[0] = (heap[0] + 1) // 2

    return total_cost * c0 + (total_cost - heap[0]) * c1

