def longest_common_increasing_subsequence(a, b):
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    prev = [[(-1, -1)] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                if not dp[i][j] or dp[i][j] < dp[i - 1][j - 1] + 1:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                    prev[i][j] = (i - 1, j - 1)
            if dp[i][j] < dp[i][j - 1]:
                dp[i][j] = dp[i][j - 1]
                prev[i][j] = (i, j - 1)
            if dp[i][j] < dp[i - 1][j]:
                dp[i][j] = dp[i - 1][j]
                prev[i][j] = (i - 1, j)

    result = []
    x, y = n, m
    while prev[x][y] != (-1, -1):
        if prev[x][y] == (x - 1, y - 1):
            result.append(a[x - 1])
        x, y = prev[x][y]

    return len(result), result[::-1]

