from itertools import permutations

def max_flow(capacity, source, sink):
    n = len(capacity)
    flow = 0

    while True:
        queue = deque([source])
        parent = [-1] * n

        while queue and parent[sink] == -1:
            u = queue.popleft()

            for v in range(n):
                if parent[v] == -1 and capacity[u][v] > 0:
                    parent[v] = u
                    queue.append(v)

        if parent[sink] == -1:
            break

        path_flow = float('Inf')
        s = sink

        while s != source:
            path_flow = min(path_flow, capacity[parent[s]][s])
            s = parent[s]

        flow += path_flow
        v = sink

        while v != source:
            u = parent[v]
            capacity[u][v] -= path_flow
            capacity[v][u] += path_flow
            v = parent[v]

    return flow

