        elif cls == 'armor':
            armors[name] = [atk, dfn, res, []]
        else:
            orbs[name] = [atk, dfn, res, []]

    for resident in residents:
        name, r_type, bonus, home = resident.split()
        bonus = int(bonus)
        if home in weapons:
            if r_type == 'gladiator':
                weapons[home][0] += bonus
            weapons[home][3].append(name)
        elif home in armors:
            if r_type == 'sentry':
                armors[home][1] += bonus
            armors[home][3].append(name)
