def count_ways(n, nums):
    total_sum = sum(nums)
    if total_sum % 3 != 0:
        return 0
    target = total_sum // 3
    ways = 0
    first_sum = 0
    count_to_target = {}
    count_to_target[0] = 1

    for i in range(n - 1):
        first_sum += nums[i]
        if first_sum == target:
            ways += count_to_target.get(target, 0)
        second_sum = 0
        for j in range(i + 1, n - 1):
            second_sum += nums[j]
            if second_sum == target:
                count_to_target[second_sum] = count_to_target.get(second_sum, 0) + 1
    return ways

