    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, parent):
        size = 1
        for neighbor in graph[node]:
            if neighbor != parent:
                size += dfs(neighbor, node)
        sizes.append(size)
