    total_size = sum(sizes)
    max_prod = 0

    for size in sizes:
        if size == total_size:
            continue
        prod = (total_size - size) * size
        max_prod = max(max_prod, prod)

    for i in range(len(sizes)):
        for j in range(i + 1, len(sizes)):
            if sizes[i] + sizes[j] == total_size:
                continue
            prod = sizes[i] * sizes[j] * (total_size - sizes[i] - sizes[j])
            max_prod = max(max_prod, prod)

    return max_prod

