def dfs(node, parent, graph):
    size = 1
    for neighbor in graph[node]:
        if neighbor != parent:
            size += dfs(neighbor, node, graph)
    return size

def max_product(node, parent, graph, total_size):
    sizes = []
    for neighbor in graph[node]:
        if neighbor != parent:
            sizes.append(dfs(neighbor, node, graph))
    total_size -= sum(sizes) + 1
    if total_size > 0:
        sizes.append(total_size)
    if len(sizes) <= 1:
        return 0
    best = 0
    for i in range(len(sizes)):
        for j in range(i + 1, len(sizes)):
            product = sizes[i] * sizes[j]
            remaining_sizes = [size for index, size in enumerate(sizes) if index != i and index != j]
            remaining_product = max_product(node, parent, graph, sum(remaining_sizes)) if remaining_sizes else 0
            best = max(best, product * remaining_product)
    return best

