def min_replant(n, m, plants):
    species_positions = [[] for _ in range(m)]
    for species, position in plants:
        species_positions[species - 1].append(position)

    def can_partition(start, end, species_index):
        if species_index == m:
            return True
        if not species_positions[species_index]:
            return False
        last_position = start
        for pos in species_positions[species_index]:
            if pos > last_position:
                last_position = pos
            else:
                return False
        return can_partition(last_position, end, species_index + 1)

    def binary_search():
        low, high = 0, n - m + 1
        while low < high:
            mid = (low + high) // 2
            if can_partition(-1, n, 0):
                high = mid
            else:
                low = mid + 1
        return low

    return binary_search()

