            if len(result) == 0 or char != result[-1]:
                result.append(char)
                used += 1
                break
        if used == k:
            cycle = result[:k]
            remaining = n - i - 1
            full_cycles = remaining // k
            result += cycle * full_cycles
            result += cycle[:remaining % k]
            return ''.join(result)

    return ''.join(result)

