def smsc_efficiency(tasks):
    queue = []
    current_time = 0
    max_queue_size = 0

    for t, c in tasks:
        while queue and queue[0] <= current_time:
            current_time += 1
            queue.pop(0)

        if current_time < t:
            current_time = t

        for _ in range(c):
            queue.append(current_time + len(queue) + 1)

        max_queue_size = max(max_queue_size, len(queue))

    while queue:
        current_time = queue.pop(0)

