    crosswords = []
    for perm in itertools.permutations(words):
        h1, v1, h2, v2, h3, v3 = perm
        if len(h1) + len(v3) != len(h2) + len(v1):
            continue

        mid_length = (len(h1) + len(v3)) // 2
        if mid_length != len(h2[:mid_length]) or mid_length != len(v1[mid_length:]):
            continue

