def generate_beads(n):
    beads = set()
    for i in range(1 << n):
        bead = []
        for j in range(n):
            bead.append((i >> j) & 1)
        bead_str = tuple(bead)
        min_bead_str = min(bead_str, tuple(map(lambda x: 1 - x, bead_str)), 
                           tuple(reversed(bead_str)), 
                           tuple(map(lambda x: 1 - x, reversed(bead_str))))
        beads.add(min_bead_str)
    sorted_beads = sorted(beads)
    return sorted_beads

