def generate_unique_strings(n):
    unique_strings = set()
    for i in range(1 << n):
        s = bin(i)[2:].zfill(n)
        min_s = min(s, s[::-1], ''.join('1' if c == '0' else '0' for c in s), 
                    ''.join('1' if c == '0' else '0' for c in s)[::-1])
        unique_strings.add(min_s)
    return sorted(unique_strings)

def kth_string(n, k):
    unique_strings = generate_unique_strings(n)
    if k <= len(unique_strings):
        return unique_strings[k-1]
    else:
