def generate_strings(n):
    from itertools import product
    strings = [''.join(p) for p in product('01', repeat=n)]
    return strings

def normalize(s):
    rev = s[::-1]
    s1 = s.replace('0', 'x').replace('1', '0').replace('x', '1')
    rev_s1 = s1[::-1]
    return min(s, rev, s1, rev_s1)

def unique_sorted_strings(n):
    strings = generate_strings(n)
    unique = set(normalize(s) for s in strings)
    return sorted(unique)

def find_kth_string(n, k):
