from collections import Counter

def is_poisson(data, mean):
    threshold = 1e-6
    poisson_cdf = [math.exp(-mean)]
    for k in range(1, max(data) + 1):
        poisson_cdf.append(poisson_cdf[-1] + math.exp(-mean) * mean**k / math.factorial(k))
    empirical_cdf = [0] * (max(data) + 1)
    total_count = len(data)
    for count in Counter(data).values():
        empirical_cdf[count - 1] += count / total_count
    for i in range(1, max(data) + 1):
        empirical_cdf[i] += empirical_cdf[i - 1]
    for p, e in zip(poisson_cdf, empirical_cdf):
        if abs(p - e) > threshold:
            return False
    return True

