from collections import Counter

def is_poisson(values, mean):
    if mean == 0:
        return all(v == 0 for v in values)
    poisson_prob = [math.exp(-mean) * mean**v / math.factorial(v) for v in range(min(values), max(values)+1)]
    expected_counts = [len(values) * p for p in poisson_prob]
    observed_counts = [values.count(v) for v in range(min(values), max(values)+1)]
    chi_square_stat = sum((obs - exp)**2 / exp if exp != 0 else float('inf') for obs, exp in zip(observed_counts, expected_counts))
    return chi_square_stat < 15.987  # approximate chi-square critical value for 95% confidence with degrees of freedom up to 10

def is_uniform(values):
    min_val, max_val = min(values), max(values)
    expected_count = len(values) / (max_val - min_val + 1)
    observed_counts = Counter(values).values()
    chi_square_stat = sum((obs - expected_count)**2 / expected_count if expected_count != 0 else float('inf') for obs in observed_counts)
    return chi_square_stat < 15.987  # approximate chi-square critical value for 95% confidence with degrees of freedom up to 10

def determine_distribution(values, population):
    adjusted_values = [v + population for v in values]
    mean = sum(adjusted_values) / len(adjusted_values)
    if is_poisson(adjusted_values, mean):
