def expected_journey_length(n, roads):
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, parent):
        if len(graph[node]) == 1 and node != 1:
            return (1, 1)
        total_length = 0
        count = 0
        for neighbor in graph[node]:
            if neighbor != parent:
                child_length, child_count = dfs(neighbor, node)
                total_length += child_length
                count += child_count
        if count == 0:
            return (0, 0)
        return (total_length + count, count)

    total_length, count = dfs(1, -1)
    return total_length / count if count > 0 else 0

